I used a distance matrix where `best[row][col]` means the smallest possible highest elevation on a path to that cell. When a neighbor is checked, its new value is `max(current value, neighbor height)`. If that value improves the stored one, the neighbor goes into the min-heap.

This is the usual shortest path pattern, except the path cost uses a maximum instead of a sum. The input grid is read only and is not modified.

```cpp
#include <vector>
#include <queue>
#include <tuple>
#include <functional>
#include <climits>
using namespace std;

class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        int n = grid.size();
        const int infinity = INT_MAX;
        vector<vector<int>> best(n, vector<int>(n, infinity));

        using State = tuple<int, int, int>;
        priority_queue<State, vector<State>, greater<State>> heap;

        best[0][0] = grid[0][0];
        heap.push({grid[0][0], 0, 0});

        int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!heap.empty()) {
            auto [water, row, col] = heap.top();
            heap.pop();

            if (water != best[row][col]) {
                continue;
            }

            if (row == n - 1 && col == n - 1) {
                return water;
            }

            for (auto& direction : directions) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];

                if (nextRow < 0 || nextRow >= n ||
                    nextCol < 0 || nextCol >= n) {
                    continue;
                }

                int needed = max(water, grid[nextRow][nextCol]);
                if (needed < best[nextRow][nextCol]) {
                    best[nextRow][nextCol] = needed;
                    heap.push({needed, nextRow, nextCol});
                }
            }
        }

        return -1;
    }
};
```

Dry run for a route with heights `0, 2, 1, 3`: the values along the route are not added. The required level changes as `0`, `2`, `2`, `3`, so the path cost is `3`.

Time complexity: `O(n^2 log(n^2))`, which is `O(n^2 log n)`.

Space complexity: `O(n^2)` for the distance matrix and heap.

Instead of binary searching the water level, this code checks each possible level from low to high. For every level, BFS finds out whether the destination can be reached through cells no higher than that level. The first successful check is the answer.

This is slower than the heap or binary search versions, but the condition is easy to follow. The starting and ending cells are included in the same height check.

```java
class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        int firstLevel = Math.max(grid[0][0], grid[n - 1][n - 1]);

        for (int level = firstLevel; level < n * n; level++) {
            if (canReach(grid, level)) {
                return level;
            }
        }

        return -1;
    }

    private boolean canReach(int[][] grid, int level) {
        int n = grid.length;
        if (grid[0][0] > level) {
            return false;
        }

        boolean[][] visited = new boolean[n][n];
        java.util.ArrayDeque<int[]> queue = new java.util.ArrayDeque<>();
        queue.offer(new int[] {0, 0});
        visited[0][0] = true;

        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int row = cell[0];
            int col = cell[1];

            if (row == n - 1 && col == n - 1) {
                return true;
            }

            for (int[] direction : directions) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];

                if (nextRow >= 0 && nextRow < n &&
                    nextCol >= 0 && nextCol < n &&
                    !visited[nextRow][nextCol] &&
                    grid[nextRow][nextCol] <= level) {
                    visited[nextRow][nextCol] = true;
                    queue.offer(new int[] {nextRow, nextCol});
                }
            }
        }

        return false;
    }
}
```

Edge cases such as a one-cell grid and a starting cell higher than the first tested level are handled by the bounds and the initial level.

Time complexity: `O(n^4)`, since there can be `O(n^2)` levels and each BFS can scan `O(n^2)` cells.

Space complexity: `O(n^2)` for the visited matrix and queue.

A path is judged by its highest cell, not by the sum of all cell heights. The heap stores the smallest water level needed to reach each next cell. When moving, the new level is the larger of the current level and the neighbor height.

A cell is marked when it is added to the heap, so it is not added many times. The one-cell grid also works because the starting cell is immediately the destination.

```java
class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        boolean[][] visited = new boolean[n][n];
        java.util.PriorityQueue<int[]> heap = new java.util.PriorityQueue<>(
            (a, b) -> Integer.compare(a[0], b[0])
        );

        heap.offer(new int[] {grid[0][0], 0, 0});
        visited[0][0] = true;
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!heap.isEmpty()) {
            int[] current = heap.poll();
            int water = current[0];
            int row = current[1];
            int col = current[2];

            if (row == n - 1 && col == n - 1) {
                return water;
            }

            for (int[] direction : directions) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];

                if (nextRow < 0 || nextRow >= n ||
                    nextCol < 0 || nextCol >= n ||
                    visited[nextRow][nextCol]) {
                    continue;
                }

                visited[nextRow][nextCol] = true;
                int nextWater = Math.max(water, grid[nextRow][nextCol]);
                heap.offer(new int[] {nextWater, nextRow, nextCol});
            }
        }

        return -1;
    }
}
```

Dry run on `[[0, 2], [1, 3]]`: the heap starts with level `0`. It adds cells with levels `1` and `2`. The lower route reaches the cell with height `3`, so the returned water level becomes `3`.

Time complexity: `O(n^2 log(n^2))`, or `O(n^2 log n)`.

Space complexity: `O(n^2)` for the heap and visited matrix.

I treated the water level as the answer we are searching for. For a fixed level, DFS only enters cells whose height is at most that level. If the bottom-right cell is reachable, a smaller level may also work, so the binary search moves left.

The grid is not changed. The visited matrix is rebuilt for every DFS check.

```cpp
#include <vector>
using namespace std;

class Solution {
    int n;
    int directions[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    bool canReach(const vector<vector<int>>& grid, int limit) {
        if (grid[0][0] > limit) {
            return false;
        }

        vector<vector<bool>> visited(n, vector<bool>(n, false));
        vector<pair<int, int>> stack;
        stack.push_back({0, 0});
        visited[0][0] = true;

        while (!stack.empty()) {
            auto [row, col] = stack.back();
            stack.pop_back();

            if (row == n - 1 && col == n - 1) {
                return true;
            }

            for (auto& direction : directions) {
                int nextRow = row + direction[0];
                int nextCol = col + direction[1];

                if (nextRow >= 0 && nextRow < n &&
                    nextCol >= 0 && nextCol < n &&
                    !visited[nextRow][nextCol] &&
                    grid[nextRow][nextCol] <= limit) {
                    visited[nextRow][nextCol] = true;
                    stack.push_back({nextRow, nextCol});
                }
            }
        }

        return false;
    }

public:
    int swimInWater(vector<vector<int>>& grid) {
        n = grid.size();
        int low = grid[0][0];
        int high = n * n - 1;

        while (low < high) {
            int middle = low + (high - low) / 2;
            if (canReach(grid, middle)) {
                high = middle;
            } else {
                low = middle + 1;
            }
        }

        return low;
    }
};
```

Time complexity: `O(n^2 log(n^2))`, which is `O(n^2 log n)`. Each binary search check visits at most every cell.

Space complexity: `O(n^2)` for the visited matrix and DFS stack.

## Approach
Search space will be the time where the minimum time will be 0 and maximum time will be the largest element in the given grid.

We will call a helper function CanReach which will perform DFS traversal for the adjacent cells.

## Solution
```csharp[]
public class Solution 
{
    private readonly int[] dRow = {-1, 0, 1, 0};
    private readonly int[] dCol = {0, -1, 0, 1};

    public int SwimInWater(int[][] grid) 
    {
        int n = grid.Length;
        int low = 0;
        int high = 0;

        //Done only for test case where n = 8 but value has 64 violating constraints
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n ; j++)
            {
                high = Math.Max(high, grid[i][j]);
            }
        }
        //int high = n * n - 1;

        int ans = 0;

        while (low <= high)
        {
            int mid = low + (high - low) / 2;

            bool[,] visited = new bool[n, n];

            if (CanReach(0, 0, mid, visited, grid, n))
            {
                ans = mid;
                high = mid - 1;
            }
            else
                low = mid + 1;
        }

        return ans;
    }

    private bool CanReach (int row, int col, int time, bool[,] visited, int[][] grid, int n)
    {
        if (!IsValid(row, col, n, n) || visited[row, col] || grid[row][col] > time)
            return false;

        //If we reached the destination return true;
        if (row == n - 1 && col == n - 1) 
            return true;

        //Mark visited as true
        visited[row, col] = true;

        //Traverse the neighbors
        for (int k = 0; k < 4; k++)
        {
            int nRow = row + dRow[k];
            int nCol = col + dCol[k];

            //DFS approach checking recursively
            if (CanReach(nRow, nCol, time, visited, grid, n))
                return true;
        }

        return false;
    }

    private bool IsValid (int i, int j, int rows, int cols)
    {
        return i >= 0 && j >= 0 && i < rows && j < cols;
    }
}

```

## Complexity
**Time Complexity:** 
O(N^2) for BFS traversal. O(log N^2) for Binary search => O(2logN)~O(logN)

Overall : O(N^2 log N)

**Space Complexity:**
O(N^2) for visited matrix, O(N^2) for recursive stack
~O(N^2)
